<script setup lang="ts">
import {computed,ref} from 'vue'
import {ACCENT_PRESETS} from '@/stores/ui'
import {studentDisplay} from '@/utils/student-display'
import {validAccent,accentText} from '@/utils/display-policy'
const props=defineProps<{values:Record<string,unknown>;disabled:boolean;models:{id:string;name:string}[]}>()
const emit=defineEmits<{change:[key:string,value:unknown]}>()
const set=(key:string,value:unknown)=>emit('change',key,value)
const config=computed(()=>studentDisplay(props.values)),previewDark=ref(false)
const color=computed(()=>validAccent(props.values.default_accent_color)?props.values.default_accent_color:'#4f46e5')
const previewStyle=computed(()=>({'--nx-accent-raw':color.value,'--nx-accent':previewDark.value?`color-mix(in srgb, ${color.value} 72%, white)`:color.value,'--nx-text-invert':accentText(color.value,previewDark.value)}))
const questions=computed(()=>Array.isArray(props.values.student_recommended_questions)?props.values.student_recommended_questions as string[]:[])
const fields=[{key:'student_brand_subtitle',label:'品牌副标题',max:60},{key:'student_welcome_title',label:'欢迎标题',max:80,placeholder:'留空使用智能体名称'},{key:'student_welcome_description',label:'欢迎说明',max:500,placeholder:'留空使用智能体简介'},{key:'student_input_placeholder',label:'输入框提示',max:160},{key:'student_footer_text',label:'底部说明',max:300},{key:'student_logo_url',label:'学校 Logo 图片',max:2048,placeholder:'HTTPS 图片地址或 /static/…'}]
const toggles=[{key:'student_show_recommendations',label:'推荐问题'},{key:'student_show_agent_cards',label:'欢迎页智能体卡片'},{key:'student_show_map_entry',label:'校园地图入口'},{key:'student_show_knowledge_shortcuts',label:'知识库快捷查询'},{key:'student_show_knowledge_sources',label:'知识来源面板'},{key:'student_show_tool_activity',label:'查询与处理过程'},{key:'student_feedback_enabled',label:'回答评价与反馈'},{key:'student_show_weather',label:'欢迎页天气'},{key:'student_onboarding_enabled',label:'首次使用引导'}]
function editQuestion(index:number,text:string){const next=questions.value.slice();next[index]=text;set('student_recommended_questions',next)}
</script>
<template>
 <div class="display-panel">
  <div class="display-caption"><strong>学生端统一显示</strong><p>保存后新页面立即使用；已打开的页面切回时更新，并每分钟同步一次。预览只展示布局，不发送聊天请求。</p></div>
  <div class="display-grid">
   <div class="display-controls">
    <section class="display-section"><h3>主题与明暗</h3>
     <el-form label-position="top" @submit.prevent>
      <el-form-item label="统一主题色"><div class="color-field"><el-color-picker :model-value="color" :disabled="disabled" :predefine="ACCENT_PRESETS.map(p=>p.value)" @update:model-value="v=>v&&set('default_accent_color',v)"/><el-input :model-value="String(values.default_accent_color||'')" aria-label="统一主题色" :disabled="disabled" placeholder="#4f46e5" @update:model-value="v=>set('default_accent_color',v)"/></div><div class="color-presets"><button v-for="preset in ACCENT_PRESETS" type="button" :key="preset.key" :style="{background:preset.value}" :aria-label="preset.label" :title="preset.label" :disabled="disabled" @click="set('default_accent_color',preset.value)"></button></div></el-form-item>
      <el-form-item label="全站统一配色"><el-switch :model-value="values.unified_theme_enabled!==false" aria-label="全站统一配色" :disabled="disabled" @update:model-value="v=>set('unified_theme_enabled',v)"/><span class="field-note">管理端和学生端使用同一主题色，个人缓存不覆盖。</span></el-form-item>
      <div class="display-pair"><el-form-item label="默认明暗模式"><el-select :model-value="values.student_default_theme||'system'" aria-label="默认明暗模式" :disabled="disabled" @update:model-value="v=>set('student_default_theme',v)"><el-option label="跟随系统" value="system"/><el-option label="浅色" value="light"/><el-option label="深色" value="dark"/></el-select></el-form-item><el-form-item label="允许个人切换明暗"><el-switch :model-value="values.student_allow_theme_toggle!==false" aria-label="允许个人切换明暗" :disabled="disabled" @update:model-value="v=>set('student_allow_theme_toggle',v)"/></el-form-item></div>
     </el-form>
    </section>
    <section class="display-section"><h3>品牌与页面文案</h3><el-form label-position="top"><el-form-item v-for="field in fields" :key="field.key" :label="field.label"><el-input :model-value="String(values[field.key]??'')" :aria-label="field.label" :disabled="disabled" :maxlength="field.max" :placeholder="field.placeholder" :type="field.key==='student_welcome_description'?'textarea':'text'" :rows="3" @update:model-value="v=>set(field.key,v)"/></el-form-item></el-form></section>
    <section class="display-section"><h3>推荐问题</h3><p class="field-note">留空使用智能体的开场问题。自定义问题会同步到学生端。</p><div v-for="(question,index) in questions" :key="index" class="question-row"><el-input :model-value="question" :aria-label="`推荐问题 ${index+1}`" :disabled="disabled" maxlength="120" @update:model-value="v=>editQuestion(index,v)"/><el-button :disabled="disabled" :aria-label="`移除推荐问题 ${index+1}`" @click="set('student_recommended_questions',questions.filter((_,i)=>i!==index))">移除</el-button></div><el-button :disabled="disabled||questions.length>=12" @click="set('student_recommended_questions',[...questions,''])">添加推荐问题</el-button></section>
    <section class="display-section"><h3>页面内容与入口</h3><div v-for="toggle in toggles" :key="toggle.key" class="display-toggle"><span>{{ toggle.label }}</span><el-switch :model-value="values[toggle.key]!==false" :aria-label="toggle.label" :disabled="disabled" @update:model-value="v=>set(toggle.key,v)"/></div><p class="field-note">这里控制页面显示。已有权限、回答中的地图和链接卡片、后台的来源审阅保持各自规则。</p></section>
    <section class="display-section"><h3>学生端模型策略</h3><el-form label-position="top"><el-form-item label="默认模型"><el-select :model-value="values.student_default_model_id||''" aria-label="学生端默认模型" :disabled="disabled" @update:model-value="v=>set('student_default_model_id',v)"><el-option label="使用平台默认模型" value=""/><el-option v-for="model in models" :key="model.id" :label="model.name" :value="model.id"/></el-select></el-form-item><el-form-item label="失败后重试模型"><el-select :model-value="values.student_fallback_model_id||''" aria-label="失败后重试模型" :disabled="disabled" @update:model-value="v=>set('student_fallback_model_id',v)"><el-option label="不自动轮换" value=""/><el-option v-for="model in models" :key="model.id" :label="model.name" :value="model.id"/></el-select></el-form-item></el-form></section>
   </div>
   <aside class="display-preview-wrap"><div class="preview-toolbar"><strong>页面预览</strong><div><el-switch v-model="previewDark" aria-label="预览夜间模式" active-text="夜间"/></div></div>
    <div class="nx-root display-preview" :class="{'is-dark':previewDark}" :style="previewStyle"><div class="preview-header"><span class="preview-seal">校</span><div><strong>{{ config.welcomeTitle||'校园智能助手' }}</strong><small>{{ config.subtitle }}</small></div><img v-if="values.student_logo_url" :src="String(values.student_logo_url)" alt="学校 Logo 预览"/></div><div class="preview-body"><div class="preview-kicker">欢迎来到校园</div><h3>{{ config.welcomeTitle||'社科大校园导览' }}</h3><p>{{ config.welcomeDescription||'课程、办事、资料都能问我。' }}</p><div v-if="config.recommendations" class="preview-questions"><span v-for="question in (questions.length?questions:['请假怎么办？','校园卡丢了怎么办？'])" :key="question">{{ question||'填写推荐问题' }}</span></div><div class="preview-example"><strong>回答内容示例</strong><p>问校园建筑位置时，会显示地图卡片；查询办理事项时，会提供相应入口。</p><div v-if="config.toolActivity" class="preview-process">查询与处理过程</div><div v-if="config.sources" class="preview-process">知识来源</div><small v-if="config.feedback">有帮助 · 没帮助</small></div></div><div class="preview-compose"><small v-if="config.mapEntry">⌖ 校园地图</small><small v-if="config.knowledgeShortcuts">知识库 · 辛瓜生存指北 · 外卖红黑榜</small><div class="preview-input"><span>{{ config.placeholder }}</span><button disabled>发送</button></div><p>{{ config.footer }}</p></div></div>
   </aside>
  </div>
 </div>
</template>
